 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    # The innermost color expands to a two-cell margin beyond the enclosing object.
    colors = {grid[r][c] for r, c in cells}
    inner = next(color for color in colors if color not in (0,))
    # In this pattern, the inner color is the color occurring least often.
    from collections import Counter
    counts = Counter(grid[r][c] for r, c in cells)
    inner = min(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(max(0, r0 - 2), min(h, r1 + 3)):
        for c in range(max(0, c0 - 2), min(w, c1 + 3)):
            if out[r][c] == 0:
                out[r][c] = inner
    return out

if __name__ == '__main__':
    demo = [[0]*19 for _ in range(13)]
    for r in range(2,10):
        for c in range(2,9): demo[r][c] = 4
    for r in range(4,8):
        for c in range(4,7): demo[r][c] = 5
    expected = [[0]*19 for _ in range(13)]
    for r in range(0,12):
        for c in range(0,11): expected[r][c] = 5
    for r in range(2,10):
        for c in range(2,9): expected[r][c] = 4
    for r in range(4,8):
        for c in range(4,7): expected[r][c] = 5
    actual = transform(demo)
    assert actual == expected, 'demo mismatch'
    test = [[0]*21 for _ in range(21)]
    for r in range(6,12):
        for c in range(5,11): test[r][c] = 3
    for r in range(7,11):
        for c in range(6,10): test[r][c] = 8
    result = transform(test)
    assert len(result) == 21 and all(len(row) == 21 for row in result)
    print('\n'.join(' '.join(map(str,row)) for row in result))
